import math

PRIOR_W = 6.0
TAGS = ("laying down", "submit", "as stated", "as required", "are one", "these are one")


def tag_hit(u):
    u = (u or "").lower()
    for t in TAGS:
        if t in u:
            return True
    return False


def branch(f):
    u = f.get("utterance", "")
    if tag_hit(u):
        return "tag"
    if f.get("formal_register") and f.get("claim_count") == 1:
        return "f1"
    return "base"


PRIORS = {"tag": 0.80, "f1": 0.72, "base": 0.25}


def est_q(hist, br):
    num = PRIORS[br] * PRIOR_W
    den = PRIOR_W
    for h in hist:
        if h.get("by") != "p3":
            continue
        f = h.get("features") or {}
        try:
            if branch(f) != br:
                continue
        except Exception:
            continue
        p = h.get("p_cards")
        if p is None:
            p = (f.get("card_math") or {}).get("p_cards", 0.0)
        p = min(max(float(p), 0.0), 0.99)
        b = 1.0 if h.get("was_bluff") else 0.0
        num += b - p
        den += 1.0 - p
    q = num / den if den > 0 else PRIORS[br]
    return min(max(q, 0.0), 1.0)


def decide(obs):
    legal = obs.get("legal_actions") or []
    hand = obs.get("my_hand") or []
    r = obs.get("table_rank", "K")
    if "play" not in legal or not hand:
        return {"type": "challenge"}
    m = [i for i, c in enumerate(hand) if c in (r, "J")]
    pc = obs.get("pending_claim")
    if pc and "challenge" in legal:
        try:
            f = pc.get("features") or {}
            p = float((f.get("card_math") or {}).get("p_cards", 0.0))
            if p >= 0.999:
                return {"type": "challenge"}
            q = est_q(obs.get("revealed_history") or [], branch(f))
            pb = p + (1.0 - p) * q
            thr = 0.5
            if not m:
                thr = 0.36
            elif len(m) >= len(hand) and len(hand) <= 3:
                thr = 0.62
            lv = obs.get("lives") or {}
            if lv.get("p1", 3) <= 1:
                thr += 0.05
            if f.get("hand_size", 5) == 0:
                thr -= 0.1
            if pb > thr:
                return {"type": "challenge"}
        except Exception:
            pass
    if m:
        cards = m[:3]
    else:
        cards = [0]
    n = len(cards)
    return {"type": "play", "cards": cards, "utterance": str(n) + " " + r + ("s" if n > 1 else "") + "."}

